// Extract input parameters
const input = $('Webhook').first().json.body.input;
const query = input.query || 'general';
const numResults = input.num_results || 5;
const recencyDays = input.recency_days || null;

// Try to parse search API results; fall back to mock data
let results = [];
try {
  const apiData = $input.first().json;
  if (apiData && apiData.results && apiData.results.length > 0) {
    results = apiData.results.slice(0, numResults).map(r => ({
      title: r.title || 'Untitled',
      url: r.url || '',
      snippet: r.content || r.snippet || ''
    }));
  }
} catch (e) {
  // API call failed or returned unexpected format
}

// If no results from API, return mock data
if (results.length === 0) {
  results = [
    {
      title: `Result 1 for "${query}"`,
      url: `https://example.com/search?q=${encodeURIComponent(query)}&r=1`,
      snippet: `This is a sample search result for your query "${query}". In production, this would come from a live search API.`
    },
    {
      title: `Result 2 for "${query}"`,
      url: `https://example.com/search?q=${encodeURIComponent(query)}&r=2`,
      snippet: `Another relevant result for "${query}". Connect a real search provider for live data.`
    },
    {
      title: `Result 3 for "${query}"`,
      url: `https://example.com/search?q=${encodeURIComponent(query)}&r=3`,
      snippet: `A third result related to "${query}". Replace with SearXNG, Google, or Brave Search API.`
    }
  ].slice(0, numResults);
}

// Filter by recency if specified (mock: just annotate)
if (recencyDays) {
  results = results.map(r => ({
    ...r,
    snippet: r.snippet + ` (filtered to last ${recencyDays} days)`
  }));
}

// Build markdown
const markdownLines = [`## Search Results for "${query}"`, ''];
results.forEach((r, i) => {
  markdownLines.push(`### ${i + 1}. ${r.title}`);
  markdownLines.push(`${r.snippet}`);
  markdownLines.push(`[${r.url}](${r.url})`);
  markdownLines.push('');
});
markdownLines.push(`---`);
markdownLines.push(`*${results.length} result(s) returned*`);
const markdownContent = markdownLines.join('\n');

// Build HTML
const htmlItems = results.map(r =>
  `<li><strong><a href="${r.url}">${r.title}</a></strong><br/>${r.snippet}</li>`
).join('\n');
const htmlContent = `<h2>Search Results for "${query}"</h2>\n<ol>\n${htmlItems}\n</ol>\n<p><em>${results.length} result(s) returned</em></p>`;

// Collect navigation URLs
const navigationUrls = results.map(r => r.url);

return [{
  json: {
    markdown_content: markdownContent,
    html_content: htmlContent,
    attachment_urls: [],
    navigation_urls: navigationUrls
  }
}];
